
(()=>{'use strict';const K='vd_perf_lite',S=localStorage.getItem(K)==='1';let lite=S,f=0,last=performance.now(),count=0;const style=document.createElement('style');style.id='vd-perf-style';style.textContent='html.vd-lite *,html.vd-lite *::before,html.vd-lite *::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}';document.head.appendChild(style);const box=document.createElement('div');box.id='vd-performance';box.style.cssText='position:fixed;top:12px;left:12px;z-index:2147483647;background:#171020ed;color:white;border:1px solid #a855f7;border-radius:12px;padding:10px;font:12px system-ui;min-width:125px;box-shadow:0 0 12px #9333ea55';box.innerHTML='<b style="color:#d8b4fe">VUDONG PERFORMANCE</b><div id="vd-fps">FPS: --</div><button id="vd-lite" style="margin-top:7px;background:#7e22ce;color:white;border:0;border-radius:7px;padding:6px 10px">Lite Mode: '+(lite?'ON':'OFF')+'</button>';document.body.appendChild(box);function apply(){document.documentElement.classList.toggle('vd-lite',lite);box.querySelector('#vd-lite').textContent='Lite Mode: '+(lite?'ON':'OFF');try{localStorage.setItem(K,lite?'1':'0')}catch(e){}}box.querySelector('#vd-lite').onclick=()=>{lite=!lite;apply()};apply();function tick(t){count++;if(t-last>=500){f=Math.round(count*1000/(t-last));box.querySelector('#vd-fps').textContent='FPS: '+f;count=0;last=t}requestAnimationFrame(tick)}requestAnimationFrame(tick);console.log('[Vudong Performance] Loaded')})();

